```go
package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

func worker(done <-chan struct{}, stopped *atomic.Int64) {
	<-done
	stopped.Add(1)
}

func main() {
	done := make(chan struct{})
	var stopped atomic.Int64
	var wg sync.WaitGroup

	for range 3 {
		wg.Go(func() { worker(done, &stopped) })
	}
	close(done)
	wg.Wait()
	fmt.Println(stopped.Load())
}
```
Main is the only closer. Every worker receives the same broadcast and WaitGroup separately confirms completion.

```go
package main

import "fmt"

func numbers(done <-chan struct{}) (<-chan int, <-chan struct{}) {
	out := make(chan int)
	stopped := make(chan struct{})
	go func() {
		defer close(out)
		defer close(stopped)
		for value := 1; ; value++ {
			select {
			case out <- value:
			case <-done:
				return
			}
		}
	}()
	return out, stopped
}

func main() {
	done := make(chan struct{})
	values, stopped := numbers(done)
	for range 3 {
		fmt.Println(<-values)
	}
	close(done)
	<-stopped
	fmt.Println("producer stopped")
}
```
The acknowledgement proves the generator returned after cancellation; main never closes the producer-owned output.

```go
package main

import (
	"context"
	"fmt"
)

func work(ctx context.Context) error {
	select {
	case <-ctx.Done():
		return ctx.Err()
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	result := make(chan error, 1)
	go func() { result <- work(ctx) }()

	cancel()
	err := <-result
	fmt.Println(err == context.Canceled)
}
```
Cancel requests shutdown; receiving the worker's result separately proves that it observed the request and returned.
